mapper.select:
SELECT * FROM agent_conversation_turn_event
WHERE tenant_id = #{tenantId}
  AND turn_id = #{turnId}
  AND dispatch_attempt = #{dispatchAttempt}
  AND event_seq = #{eventSeq}
ORDER BY chunk_index ASC

SELECT * FROM agent_conversation_turn_event
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND id > #{afterId}
ORDER BY id ASC
LIMIT #{limit}

SELECT * FROM agent_conversation_turn_event
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND turn_id = #{turnId}
ORDER BY event_seq ASC, chunk_index ASC
LIMIT #{limit}

SELECT * FROM agent_conversation_turn_event
WHERE tenant_id = #{tenantId} AND conversation_id = #{conversationId}
  AND turn_id = #{turnId} AND id > #{afterId}
ORDER BY id ASC LIMIT #{limit}

SELECT * FROM agent_conversation_turn_event
WHERE tenant_id = #{tenantId} AND turn_id = #{turnId}
  AND dispatch_attempt < #{dispatchAttempt} AND event_seq = #{eventSeq}
ORDER BY dispatch_attempt DESC, chunk_index ASC

SELECT * FROM agent_conversation_turn_event
WHERE tenant_id = #{tenantId} AND conversation_id = #{conversationId}
  AND turn_id = #{turnId} AND event_type <> 'status'
ORDER BY event_seq DESC, chunk_index DESC, id DESC
LIMIT #{limit}

SELECT * FROM agent_conversation_turn_event
WHERE tenant_id = #{tenantId} AND conversation_id = #{conversationId}
  AND turn_id = #{turnId} AND event_type = 'status'
ORDER BY event_seq ASC, chunk_index ASC, id ASC
LIMIT #{limit}

SELECT gmt_create FROM agent_conversation_turn_event
WHERE tenant_id = #{tenantId} AND conversation_id = #{conversationId}
  AND turn_id = #{turnId}
ORDER BY id DESC LIMIT 1

SELECT 1 FROM agent_conversation_turn_event
WHERE tenant_id = #{tenantId} AND turn_id = #{turnId}
  AND dispatch_attempt < #{dispatchAttempt}
LIMIT 1
